  gz_jiubian_xunu: {
    audio: "gz_zhangren",
    trigger: { player: "phaseZhunbeiBegin" },
    preHidden: true,
    filter(event2, player2) {
      return lib.skill.gz_jiubian_xunu.getRelations(player2).length > 0;
    },
    async cost(event2, trigger, player2) {
      const relations = lib.skill.gz_jiubian_xunu.getRelations(player2);
      const choiceList = relations.map((relation) => `${relation.type}：${get.translation(relation.players)}`);
      const result = await player2.chooseControl("cancel2").set("prompt", get.prompt2(event2.skill)).set("choiceList", choiceList).set("relations", relations).set("ai", () => {
        const player3 = get.player();
        const relations2 = _status.event.relations;
        let choice = "cancel2", value = 0;
        for (let i = 0; i < relations2.length; i++) {
          const effect = relations2[i].targets.reduce((sum, target) => sum + get.effect(target, { name: "diaohulishan" }, player3, player3), 0);
          if (effect > value) {
            value = effect;
            choice = `选项${get.cnNumber(i + 1, true)}`;
          }
        }
        return choice;
      }).forResult();
      if (result.control == "cancel2") {
        event2.result = { bool: false };
      } else {
        event2.result = { bool: true, cost_data: relations[result.index] };
      }
    },
    async content(event2, trigger, player2) {
      const relation = event2.cost_data;
      if (!relation || !relation.targets || !relation.targets.length) {
        return;
      }
      const targets = relation.targets.filter((target) => target.isIn());
      if (!targets.length) {
        return;
      }
      await player2.useCard({ card: { name: "diaohulishan", isCard: true }, targets, addCount: false });
      const num = targets.length - player2.countCards("h");
      if (num > 0) {
        await player2.draw(num);
      }
    },
    getRelations(player2) {
      const relations = [], keys = [], card2 = { name: "diaohulishan", isCard: true };
      for (const group of lib.skill.gz_jiubian_xunu.getInlineGroups()) {
        const targets = group.filter((target) => target != player2 && player2.canUse(card2, target, false));
        if (!targets.length) {
          continue;
        }
        const key = "inline:" + group.map((current) => current.playerid).sort().join(":");
        if (!keys.includes(key)) {
          keys.push(key);
          relations.push({ type: "队列", players: group, targets });
        }
      }
      for (const group of lib.skill.gz_jiubian_xunu.getSiegeGroups()) {
        const targets = group.filter((target) => target != player2 && player2.canUse(card2, target, false));
        if (!targets.length) {
          continue;
        }
        const key = "siege:" + group.map((current) => current.playerid).sort().join(":");
        if (!keys.includes(key)) {
          keys.push(key);
          relations.push({ type: "围攻", players: group, targets });
        }
      }
      return relations;
    },
    getInlineGroups() {
      const players = game.filterPlayer((current) => current.isIn()), groups = [], keys = [];
      for (const player2 of players) {
        if (!player2.inline()) {
          continue;
        }
        const group = players.filter((current) => current == player2 || current.inline(player2)).sortBySeat();
        if (group.length < 2) {
          continue;
        }
        const key = group.map((current) => current.playerid).sort().join(":");
        if (!keys.includes(key)) {
          keys.push(key);
          groups.push(group);
        }
      }
      return groups;
    },
    getSiegeGroups() {
      const players = game.filterPlayer((current) => current.isIn()), groups = [], keys = [];
      for (const target of players) {
        const next = target.getNext(), previous = target.getPrevious();
        if (!lib.skill.gz_jiubian_cegu.isSiegedInList(target, next, previous)) {
          continue;
        }
        const group = [target, next, previous].sortBySeat();
        const key = group.map((current) => current.playerid).sort().join(":");
        if (!keys.includes(key)) {
          keys.push(key);
          groups.push(group);
        }
      }
      return groups;
    }
  },
