      return player2.getHistory("useCard", (evt) => evt !== event2 && get.suit(evt.card) === suit && lib.skill.quanbian.hasHand(evt) && evt.getParent("phaseUse") === phase).length + player2.getHistory("respond", (evt) => evt !== event2 && get.suit(evt.card) === suit && lib.skill.quanbian.hasHand(evt) && evt.getParent("phaseUse") === phase).length === 0;
