    ai: {
      order(skill2, player2) {
        if (game.hasPlayer(function(current) {
          return current.hp < current.maxHp && current != player2 && get.recoverEffect(current, player2, player2) > 0;
        })) {
          return 10;
        }
        return 1;
      },
      result: {
        player(player2, target) {
          if (get.attitude(player2, target) < 0) {
            return -1;
          }
          let eff = get.recoverEffect(target, player2, player2);
          if (eff < 0) {
            return 0;
          }
          if (eff > 0) {
            if (target.hp == 1) {
              return 3;
            }
            return 2;
          }
          if (player2.needsToDiscard()) {
            return 1;
          }
          return 0;
        }
      },
      threaten: 1.3
    }
