      player2.addMark(name, 1, false);
      let num = -1;
      let left = player2;
      let right = player2;
      while (target?.isIn()) {
        if (left === target || right === target) {
          break;
        }
        left = left.getPrevious();
        right = right.getNext();
        num++;
      }
      await player2.draw(Math.max(1, num));
      if (target !== player2) {
        const result = await target.chooseBool({ prompt: `是否与${get.translation(player2)}交换副将？` }).set("choice", Math.random() > 0.5).forResult();
        if (result.bool) {
          player2.addTempSkill(`${event2.name}_more`, { global: "roundStart" });
          player2.addMark(`${event2.name}_more`, 1, false);
          await player2.transCharacter(target);
        }
      }
