    subSkill: {
      count: {
        sub: true,
        trigger: { global: "recoverAfter" },
        silent: true,
        filter(event2) {
          return event2.getParent("jianglue");
        },
        async content(event2, trigger, player2) {
          player2.storage.jianglue_count++;
        }
      }
    }
